  1	//! MUSIC (MUltiple SIgnal Classification) algorithm for Direction-of-Arrival estimation.
  2	
  3	use std::f64::consts::PI;
  4	
  5	use nalgebra::DMatrix;
  6	use nalgebra::DVector;
  7	use num_complex::Complex;
  8	
  9	use crate::error::{MusicError, Result};
 10	use crate::stft::{analytic_signal, stft};
 11	
 12	/// Speed of sound in air at ~20 °C, in metres per second.
 13	const SPEED_OF_SOUND: f64 = 343.2;
 14	
 15	/// Power ratio (−260 dB) below which a signal counts as silent: above the rounding residue
 16	/// left by removing a constant offset or by FFT leakage from an on-bin tone (about
 17	/// ε² ≈ 5e-32 times a small factor), but low enough that a quiet tone on a large DC
 18	/// offset (say 1e-5 on 1e6, a ratio of 1e-22) still counts as signal.
 19	const SILENCE_RATIO: f64 = 1e-26;
 20	
 21	/// Default Kinect microphone array positions `(x, y)` in metres.
 22	const DEFAULT_ANTENNA_POSITIONS: [[f64; 2]; 4] =
 23	    [[0.113, 0.0], [-0.036, 0.0], [-0.076, 0.0], [-0.113, 0.0]];
 24	
 25	// ─────────────────────────────────────────────────────────────────────────────
 26	// Type aliases
 27	// ─────────────────────────────────────────────────────────────────────────────
 28	type Cplx = Complex<f64>;
 29	type CMatrix = DMatrix<Cplx>;
 30	type CVec = DVector<Cplx>;
 31	
 32	// ─────────────────────────────────────────────────────────────────────────────
 33	// Hermitian eigendecomposition (pure nalgebra, no LAPACK)
 34	// ─────────────────────────────────────────────────────────────────────────────
 35	
 36	/// Eigendecomposition of a complex Hermitian n×n matrix using faer's dedicated
 37	/// complex selfadjoint solver, which is numerically more stable than the real
 38	/// block-matrix trick for near-degenerate noise subspaces.
 39	///
 40	/// Returns `(eigenvalues, eigenvectors)` sorted by ascending eigenvalue.
 41	/// `eigenvalues[k]` is real; `eigenvectors.column(k)` is the unit-norm eigenvector.
 42	fn hermitian_eigen(mat: &CMatrix) -> (Vec<f64>, CMatrix) {
 43	    use faer::complex_native::c64;
 44	    use faer::{Mat as FaerMat, Side};
 45	
 46	    let n = mat.nrows();
 47	
 48	    // Convert nalgebra complex matrix → faer complex matrix
 49	    let faer_mat: FaerMat<c64> = FaerMat::from_fn(n, n, |i, j| {
 50	        let c = mat[(i, j)];
 51	        c64::new(c.re, c.im)
 52	    });
 53	
 54	    // Numerically stable Hermitian eigendecomposition
 55	    // Note: faer does not guarantee a sort order, so we sort ascending afterward.
 56	    let evd = faer_mat.selfadjoint_eigendecomposition(Side::Lower);
 57	
 58	    // Eigenvalues are real but stored as c64 with im ≈ 0; extract via .re
 59	    let s_col = evd.s().column_vector();
 60	    let u_mat = evd.u();
 61	
 62	    // Sort by ascending (real) eigenvalue
 63	    let mut order: Vec<usize> = (0..n).collect();
 64	    order.sort_unstable_by(|&a, &b| s_col.read(a).re.total_cmp(&s_col.read(b).re));
 65	
 66	    let eigenvalues: Vec<f64> = order.iter().map(|&i| s_col.read(i).re).collect();
 67	    // Copy the eigenvectors (reordered by ascending eigenvalue) back into nalgebra.
 68	    // faer's eigenvectors already satisfy A·v = λ·v, so no conjugation is applied;
 69	    // the steering-vector sign convention in `steering_vector` is matched to this.
 70	    let eigenvectors: CMatrix = CMatrix::from_fn(n, n, |row, col| {
 71	        let src_col = order[col];
 72	        let c = u_mat.read(row, src_col);
 73	        Cplx::new(c.re, c.im)
 74	    });
 75	
 76	    (eigenvalues, eigenvectors)
 77	}
 78	
 79	// ─────────────────────────────────────────────────────────────────────────────
 80	// Peak detection
 81	// ─────────────────────────────────────────────────────────────────────────────
 82	
 83	/// Returns the angles of the `n` highest peaks in `scores`, sorted by descending peak
 84	/// height.
 85	///
 86	/// A peak is a run of one or more equal neighbouring scores that is strictly higher than
 87	/// the scores on either side of it; it is reported at the run's midpoint. Runs of equal
 88	/// scores happen on symmetric spectra: a line array's spectrum is mirror-symmetric, so a
 89	/// source at endfire between two grid points scores exactly the same on both.
 90	///
 91	/// With `circular` (the grid covers the full circle), the first and last points are
 92	/// neighbours and a run may wrap around. Otherwise they are the two ends of an open range
 93	/// with only one neighbour each, so a spectrum still rising at an end of the range peaks
 94	/// there. A spectrum that is constant over a grid of two or more points has no peak; a
 95	/// one-point open grid peaks at its only point.
 96	fn find_peaks(scores: &[f64], angles: &[f64], n: usize, circular: bool) -> Vec<f64> {
 97	    let len = scores.len();
 98	    if len == 0 || n == 0 {
 99	        return Vec::new();
100	    }
101	
102	    // Runs of equal scores as inclusive index ranges.
103	    let mut runs: Vec<(usize, usize)> = Vec::new();
104	    let mut run_start = 0;
105	    for i in 1..=len {
106	        if i == len || scores[i] != scores[run_start] {
107	            runs.push((run_start, i - 1));
108	            run_start = i;
109	        }
110	    }
111	    if runs.len() == 1 {
112	        // A single point on an open range has no neighbours, so it is a peak (as for
113	        // `angle_steps_num = 1`); a longer constant spectrum has none.
114	        return if len == 1 && !circular {
115	            vec![angles[0]]
116	        } else {
117	            Vec::new()
118	        };
119	    }
120	    // On the circle, a run at the start continues the run at the end. Its indices then
121	    // go past `len` and are taken modulo `len`.
122	    if circular && scores[0] == scores[len - 1] {
123	        let (_, first_end) = runs.remove(0);
124	        runs.last_mut().unwrap().1 = first_end + len;
125	    }
126	
127	    let score = |i: usize| scores[i % len];
128	    let midpoint = |(a, b): (usize, usize)| {
129	        if b < len {
130	            (angles[a] + angles[b]) / 2.0
131	        } else {
132	            let step = angles[1] - angles[0];
133	            let mid = (a + b) as f64 / 2.0;
134	            if mid >= len as f64 {
135	                angles[0] + step * (mid - len as f64)
136	            } else {
137	                angles[a] + step * (mid - a as f64)
138	            }
139	        }
140	    };
141	
142	    let r = runs.len();
143	    let mut peaks: Vec<(f64, f64)> = (0..r)
144	        .filter_map(|k| {
145	            let (a, b) = runs[k];
146	            let prev = match k {
147	                0 if circular => Some(score(runs[r - 1].1)),
148	                0 => None,
149	                _ => Some(score(runs[k - 1].1)),
150	            };
151	            let next = match k + 1 {
152	                j if j < r => Some(score(runs[j].0)),
153	                _ if circular => Some(score(runs[0].0)),
154	                _ => None,
155	            };
156	            let v = score(a);
157	            (prev.is_none_or(|p| v > p) && next.is_none_or(|q| v > q))
158	                .then(|| (v, midpoint((a, b))))
159	        })
160	        .collect();
161	
162	    peaks.sort_unstable_by(|a, b| b.0.total_cmp(&a.0));
163	    peaks.into_iter().take(n).map(|(_, a)| a).collect()
164	}
