166	// ─────────────────────────────────────────────────────────────────────────────
167	// Bin selection for IFB-MUSIC
168	// ─────────────────────────────────────────────────────────────────────────────
169	
170	/// Picks the STFT bins that carry signal, for [`MusicEstimator::ifb_music_spectrum`].
171	///
172	/// IFB-MUSIC weights every bin equally, so bins holding only noise point the merged
173	/// spectrum in arbitrary directions. This keeps the bins whose power is within
174	/// `threshold_db` of the strongest bin. A bin's power is the trace of its cross-spectral
175	/// matrix: `|X|²` summed over microphones and averaged over windows, using the same
176	/// non-overlapping `nfft`-sample STFT windows as `ifb_music_spectrum`.
177	///
178	/// The DC bin is never selected (as with `bins = None`). Returns bin indices in ascending
179	/// order.
180	///
181	/// A tone between two bins leaks into its neighbours, and each selected bin is steered at
182	/// the bin's frequency rather than the tone's. The mismatch shifts the estimate, most
183	/// near endfire (0° / 180° for a line array): on the test recordings at `nfft = 1024`
184	/// (15.6 Hz bins), a single tone is off by up to 5.5° at 0° and 1.5° elsewhere. Choose
185	/// `nfft` so the tones fall on bins where possible.
186	///
187	/// # Errors
188	/// - [`MusicError::InvalidThreshold`] if `threshold_db` is negative or not finite.
189	/// - [`MusicError::InvalidNfft`] if `nfft` is 0; [`MusicError::NoUsableBins`] if it is
190	///   1 (the only bin is DC).
191	/// - [`MusicError::EmptyData`], [`MusicError::NonFiniteData`] or
192	///   [`MusicError::DataShorterThanWindow`] for unusable data.
193	/// - [`MusicError::SilentData`] if every bin except DC has zero power.
194	///
195	/// # Examples
196	/// ```
197	/// use musicrs::{MusicEstimator, select_bins_by_energy};
198	/// use nalgebra::DMatrix;
199	/// use std::f64::consts::PI;
200	///
201	/// // A 1 kHz tone: with nfft = 160 at 16 kHz the bins are 100 Hz apart, so it is bin 10.
202	/// let est = MusicEstimator::default();
203	/// let data = DMatrix::from_fn(4, 16000, |_, t| (2.0 * PI * 1000.0 * t as f64 / 16000.0).cos());
204	/// let bins = select_bins_by_energy(&data, 160, 20.0)?;
205	/// assert_eq!(bins, [10]);
206	/// let (spectrum, angles) = est.ifb_music_spectrum(&data, 160, 1, Some(&bins))?;
207	/// # let _ = (spectrum, angles);
208	/// # Ok::<(), musicrs::MusicError>(())
209	/// ```
210	pub fn select_bins_by_energy(
211	    data: &DMatrix<f64>,
212	    nfft: usize,
213	    threshold_db: f64,
214	) -> Result<Vec<usize>> {
215	    if !(threshold_db.is_finite() && threshold_db >= 0.0) {
216	        return Err(MusicError::InvalidThreshold(threshold_db));
217	    }
218	    if nfft == 0 {
219	        return Err(MusicError::InvalidNfft);
220	    }
221	    if nfft == 1 {
222	        return Err(MusicError::NoUsableBins);
223	    }
224	    check_real_samples(data)?;
225	    if data.ncols() < nfft {
226	        return Err(MusicError::DataShorterThanWindow {
227	            nfft,
228	            samples: data.ncols(),
229	        });
230	    }
231	    let mut power = vec![0.0; nfft / 2 + 1];
232	    for m in 0..data.nrows() {
233	        let row: Vec<f64> = data.row(m).iter().copied().collect();
234	        for (p, bin) in power.iter_mut().zip(stft(&row, nfft, 0)?) {
235	            *p += bin.iter().map(|c| c.norm_sqr()).sum::<f64>() / bin.len() as f64;
236	        }
237	    }
238	    let strongest = power[1..].iter().copied().fold(0.0, f64::max);
239	    if strongest <= 0.0 {
240	        return Err(MusicError::SilentData);
241	    }
242	    let floor = strongest * 10f64.powf(-threshold_db / 10.0);
243	    Ok((1..power.len()).filter(|&k| power[k] >= floor).collect())
244	}
