246	/// A power of two close to `max_abs`, the largest absolute value in some data, to divide
247	/// the data by. MUSIC does not depend on the data's scale, and dividing by a power of two
248	/// is exact, so this changes no result: it only keeps the sums of squares in the
249	/// covariance and energy from overflowing for very loud data (or underflowing for very
250	/// quiet data).
251	fn power_of_two_scale(max_abs: f64) -> f64 {
252	    if max_abs > 0.0 {
253	        2f64.powi((max_abs.log2().floor() as i32).clamp(-1000, 1000))
254	    } else {
255	        1.0
256	    }
257	}
