264	/// The mean of `values`, summed with Neumaier's compensated summation so that it is
265	/// correct to about one ulp: subtracting it from constant data then leaves (almost)
266	/// nothing, which [`SILENCE_RATIO`] relies on. With a plain sum, 16000 samples of 0.3
267	/// leave a residue above the threshold.
268	fn accurate_mean<'a>(values: impl ExactSizeIterator<Item = &'a f64>) -> f64 {
269	    let n = values.len() as f64;
270	    let (mut sum, mut compensation) = (0.0_f64, 0.0_f64);
271	    for &x in values {
272	        let t = sum + x;
273	        compensation += if sum.abs() >= x.abs() {
274	            (sum - t) + x
275	        } else {
276	            (x - t) + sum
277	        };
278	        sum = t;
279	    }
280	    (sum + compensation) / n
281	}
