423	    /// Element *j* is `exp(+i·2π·f·τⱼ)` where `τⱼ = (pⱼ · d̂) / c` is the projection of
424	    /// antenna *j*'s position onto the arrival direction, divided by the speed of sound. This
425	    /// matches the non-conjugated [`analytic_signal`] and STFT bins
426	    /// (pyMUSIC conjugates its analytic signal and uses `exp(−i·2π·f·τⱼ)`; the two agree below
427	    /// Nyquist). Relative to [`sample_rate`](Self::sample_rate):
428	    /// * above Nyquist the exponent is negated, `exp(−i·2π·f·τⱼ)`, because the recorded tone
429	    ///   is aliased and its phase is conjugated;
430	    /// * within 0.5 Hz of Nyquist the vector is real, `cos(2π·f·τⱼ)`, because the analytic
431	    ///   signal there is real too.
432	    ///
433	    /// # Examples
434	    /// ```
435	    /// use musicrs::MusicEstimator;
436	    /// let est = MusicEstimator::default();
437	    /// let sv = est.steering_vector(0.0, 300.0);
438	    /// assert_eq!(sv.len(), 4);
