444	    pub fn steering_vector(&self, angle: f64, frequency: f64) -> CVec {
445	        let dir = [angle.cos(), angle.sin()];
446	        // For f < Nyquist (sr/2): analytic signal has positive phase → use +exponent.
447	        // For f > Nyquist: signal aliases in the one-sided FFT; dominant eigenvector
448	        // phase is conjugated → use −exponent.
449	        // At exactly Nyquist (f == sr/2): analytic signal is real; noise subspace is
450	        // also real → use cos(phase) as a real steering vector.
451	        let nyquist = self.sample_rate / 2.0;
452	        let phase_sign = if frequency > nyquist {
453	            -1.0_f64
454	        } else {
455	            1.0_f64
456	        };
457	        let at_nyquist = (frequency - nyquist).abs() < 0.5;
458	        CVec::from_iterator(
459	            self.n_antennas(),
460	            self.antenna_positions.iter().map(|p| {
461	                let delay = (p[0] * dir[0] + p[1] * dir[1]) / SPEED_OF_SOUND;
462	                let phase = phase_sign * 2.0 * PI * frequency * delay;
463	                if at_nyquist {
464	                    // Real steering vector: imaginary part is zero
465	                    Cplx::new(phase.cos(), 0.0)
466	                } else {
467	                    Cplx::from_polar(1.0, phase)
468	                }
469	            }),
470	        )
471	    }
